from typing import Optional


class AHLogResult:
    def __init__(self, result: Optional[int] = None, message: Optional[str] = None,
                 api_response: Optional[dict] = None):
        self.result = result
        self.message = message
        self.api_response = api_response


class AHAlertResult:
    def __init__(self, code: Optional[int] = None, message: Optional[str] = None,
                 data: Optional[dict] = None):
        self.code = code
        self.message = message
        self.data = data


class AHAdoptionResult:
    def __init__(self, returncode: Optional[int] = None, message: Optional[str] = None,
                 result: Optional[dict] = None):
        self.returncode = returncode
        self.message = message
        self.result = result


class AHCommonResult:
    def __init__(self, returncode: Optional[int] = None, message: Optional[str] = None,
                 result: Optional[dict] = None):
        self.returncode = returncode
        self.message = message
        self.result = result
